entries[142877] = { ["name"] = "Instabiler Umschlag", ["text"] = "100 Meter Reichweite\nSofort\nStärkt die Antikörper des Ziels in Höhe eines eintreffenden Heilzaubers.\nWenn das Ziel das nächste Mal Schaden erleidet, werden die natürlichen Heilungsprozesse des Ziels aktiviert und es wird um die angesammelte Heilmenge geheilt." }
entries[142878] = { ["name"] = "Verzauberter Feendrache", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren verzauberten Feendrachen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n\"Diese majestätische Kreatur ist Wolkenglanzes älterer Bruder. Er versichert, dass sie eigentlich adoptiert wurde.\"\nWoW-Shop" }
entries[142879] = { ["name"] = "Blutrausch", ["text"] = "Wirken in 2.5 sek.\nMalkorok gerät in Zorn und jeder seiner Nahkampfangriffe verursacht 37617 körperlichen Schaden, der unter allen getroffenen Zielen aufgeteilt wird. 'Blutrausch' bewirkt, dass Malkorok pro Sekunde 5 Wut verliert und der Effekt endet, wenn Malkorok keine Wut mehr übrig hat." }
