entries[142894] = { ["name"] = "Aufwärtsschlitzer", ["text"] = "8 Meter Reichweite\nWirken in 2 sek.\nSchlagt einen Feind nieder und fügt 14 Schaden zu.\n\nWenn der Feind mit einem Degen pariert, wird der Angriff abgewehrt und verursacht keinen Schaden." }
