entries[142913] = { ["name"] = "Verdrängte Energie", ["text"] = "Sofort\nDie Macht von Y'Shaarj springt auf Gegner in der Nähe über und verursacht 9 Sek. lang alle 3 Sek. 5225 Schattenschaden. Wenn 'Verdrängte Energie' endet, explodiert die Energie und fügt allen Zielen innerhalb von 8 Metern 9404 Schattenschaden zu." }
