entries[142944] = { ["name"] = "Steinabbild", ["text"] = "Sofort\nEntzieht Spielercharakteren einen Teil ihrer Lebensessenz, stößt sie zurück und fügt ihnen 171 Schattenschaden zu. Aus der Lebensessenz wird eine Steinstatue erstellt.\n\nDiese Statue schlägt regelmäßig auf den Boden. Dadurch fügt sie allen Zielen in einem kegelförmigen Bereich vor ihr 41 körperlichen Schaden zu und betäubt sie lang. Diese Statue bleibt bestehen, bis sie getötet wird." }
entries[142945] = { ["name"] = "Schauriger Nebel", ["text"] = "100 Meter Reichweite\nSofort\nFügt dem Ziel alle 3 Sek. 34 Naturschaden zu." }
entries[142947] = { ["name"] = "Blutrote Rekonstitution", ["text"] = "Unbegrenzte Reichweite\nWirken in 1.5 sek. 5 sek. Abklingzeit\nVerteilt 45 Sek. lang Animapfützen um nahe Einheiten. Alle Ziele, die sich in einem solchen Bereich aufhalten, werden pro Sekunde um 10% ihrer maximalen Gesundheit geheilt." }
