entries[142951] = { ["name"] = "Gamaschen der weißen Wolken", ["text"] = "Wirken in 2 sek.\nReagenzien:\nHimmlischer Stoff (28)\nBeruf:\nSchneiderei von Pandaria (75)\nEntdeckung:\nHimmlischer Stoff\n\nGamaschen der weißen Wolken\nWird beim Anlegen gebunden\nBeine Stoff\n4 Rüstung\n+2 Intelligenz\n+7 Ausdauer\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 2.\n\nPrismatischer Sockel\nPrismatischer Sockel\nSockelbonus: + 4 Intelligenz\n\nHaltbarkeit 120 / 120\n35" }
