entries[142980] = { ["name"] = "Implodierende Energie", ["text"] = "100 Meter Reichweite\nSofort\nEnergie entlädt sich von Malkorok und verursacht eine Implosion. Die Implosion fügt allen Gegnern im Umkreis von 5 Metern nach 4 Sek. 9404 Schattenschaden zu. Wenn die Implosion keine Gegner trifft, verursacht sie stattdessen eine Explosion, die allen Gegnern im Umkreis von 200 Metern 10662 Schattenschaden zufügt." }
